def transform(grid):
    result = [row[:] for row in grid]
    height = len(grid)
    width = len(grid[0])

    frequencies = {}
    for row in grid:
        for cell in row:
            frequencies[cell] = frequencies.get(cell, 0) + 1

    background = max(frequencies, key=frequencies.get)
    others = [cell for cell in frequencies if cell != background]
    wall = max(others, key=lambda cell: frequencies[cell])
    doorway = min((cell for cell in others if cell != wall),
                  key=lambda cell: -frequencies[cell])
    ink = min(others, key=lambda cell: frequencies[cell])

    points = [(r, c) for r in range(height) for c in range(width)
              if grid[r][c] == ink]
    points.sort()
    source, target = points

    openings = []
    for r in range(height):
        cs = [c for c in range(width) if grid[r][c] == doorway]
        if cs:
            openings.append((r, cs[len(cs) // 2]))

    result[target[0]][target[1]] = background

    current_r, current_c = source
    for door_r, door_c in openings:
        turn_r = door_r - 1
        for r in range(current_r, turn_r + 1):
            result[r][current_c] = ink
        step = 1 if door_c >= current_c else -1
        for c in range(current_c, door_c + step, step):
            result[turn_r][c] = ink
        result[door_r][door_c] = ink
        current_r, current_c = door_r, door_c

    final_r = target[0] - 1
    for r in range(current_r, final_r + 1):
        result[r][current_c] = ink
    step = 1 if target[1] >= current_c else -1
    for c in range(current_c, target[1] + step, step):
        result[final_r][c] = ink

    # Restore every wall cell except the centers of the doorways.
    opening_centers = set(openings)
    for r in range(height):
        for c in range(width):
            if grid[r][c] == wall:
                result[r][c] = wall
            elif grid[r][c] == doorway and (r, c) not in opening_centers:
                result[r][c] = doorway
    return result
